def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")

    # Base case
    if n == 0:
        return 1

    # Dynamic programming approach
    # C(n) = sum_{i=0}^{n-1} C(i) * C(n-1-i)
    catalan = [0] * (n + 1)
    catalan[0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - 1 - j]

    return catalan[n]
```

